import type { MutableRefObject, ReactElement } from 'react';
import { useMemo, useState } from 'react';

import { useIntl } from 'react-intl';

import {
  Badge,
  ESwitchSize,
  Icon,
  Image,
  Input,
  ListView,
  ScrollView,
  SizableText,
  Stack,
  XStack,
  YStack,
} from '@onekeyhq/components';
import NumberSizeableTextWrapper from '@onekeyhq/kit/src/components/NumberSizeableTextWrapper';
import { TokenSelectorLpTokenSwitch } from '@onekeyhq/kit/src/components/TokenSelectorFilter';
import { ETranslations } from '@onekeyhq/shared/src/locale';
import type { IFuseResult } from '@onekeyhq/shared/src/modules3rdParty/fuse';
import type {
  ISwapNetwork,
  ISwapToken,
} from '@onekeyhq/shared/types/swap/types';

import SwapPopularTokenGroup from '../SwapPopularTokenGroup';

import { buildSwapTokenSelectorNetworkGroups } from './SwapTokenSelectorDesktop.utils';

import type { ISwapNetworkAsset } from './SwapTokenSelectorDesktop.utils';
import type { FlatList } from 'react-native';

type ISwapTokenItem = ISwapToken | IFuseResult<ISwapToken>;

type ISwapTokenSelectorDesktopProps = {
  allNetwork: ISwapNetwork;
  networks: ISwapNetwork[];
  sameChainNetwork?: ISwapNetwork;
  selectedNetwork?: ISwapNetwork;
  assetNetworks: ISwapNetworkAsset[];
  disableNetworks: string[];
  networkSearchValue: string;
  tokenSearchValue: string;
  tokenSearchPlaceholder: string;
  allNetworksLabel: string;
  sameChainLabel: string;
  onNetworkSearchChange: (value: string) => void;
  onTokenSearchChange: (value: string) => void;
  onSelectNetwork: (network: ISwapNetwork) => void;
  onDisableNetworksClick: () => void;
  onSelectToken: (token: ISwapToken) => void;
  listViewRef?: MutableRefObject<FlatList<ISwapTokenItem> | null>;
  popularTokens: ISwapToken[];
  showPopularTokens: boolean;
  showLpTokenFilterSwitch: boolean;
  showLpTokensOnly: boolean;
  onLpTokenFilterChange: (value: boolean) => void;
  tokens: ISwapTokenItem[];
  renderToken: (params: {
    item: ISwapTokenItem;
    index: number;
  }) => ReactElement | null;
  currencySymbol: string;
  tokenListEmptyComponent?: ReactElement | null;
};

function NetworkLogo({ network }: { network: ISwapNetwork }) {
  if (network.isAllNetworks) {
    return <Icon name="AllNetworksSolid" size="$6" color="$iconActive" />;
  }
  if (network.logoURI) {
    return (
      <Image size="$6" borderRadius="$full" source={{ uri: network.logoURI }} />
    );
  }
  return <Icon name="GlobusOutline" size="$6" color="$iconSubdued" />;
}

// Sections of the network column that may list the same network.
type INetworkSection = 'sameChain' | 'assets' | 'all';

function NetworkRow({
  network,
  selected,
  disabled,
  indented,
  badgeText,
  fiatValue,
  currencySymbol,
  onPress,
}: {
  network: ISwapNetwork;
  selected: boolean;
  disabled: boolean;
  indented?: boolean;
  badgeText?: string;
  fiatValue?: string;
  currencySymbol: string;
  onPress: () => void;
}) {
  return (
    <XStack
      role="button"
      focusable
      userSelect="none"
      alignItems="center"
      height={44}
      px={9}
      // Indent child rows with margin, not padding, so the selected
      // border/background starts right of the group guide line.
      ml={indented ? 26 : 0}
      gap="$2"
      borderWidth={1}
      borderColor={selected ? '$border' : '$transparent'}
      borderRadius="$3"
      bg={selected ? '$bgSubdued' : undefined}
      opacity={disabled ? 0.5 : 1}
      hoverStyle={disabled ? undefined : { bg: '$bgHover' }}
      pressStyle={disabled ? undefined : { bg: '$bgActive' }}
      focusVisibleStyle={{
        outlineColor: '$focusRing',
        outlineStyle: 'solid',
        outlineWidth: 2,
        outlineOffset: 2,
      }}
      onPress={onPress}
    >
      <NetworkLogo network={network} />
      <SizableText size="$bodyMdMedium" flex={1} numberOfLines={1}>
        {network.name}
      </SizableText>
      {badgeText ? (
        <Badge badgeType="default" badgeSize="sm" borderRadius="$1.5">
          <Badge.Text>{badgeText}</Badge.Text>
        </Badge>
      ) : null}
      {fiatValue ? (
        <NumberSizeableTextWrapper
          hideValue
          size="$bodySm"
          color="$textSubdued"
          formatter="value"
          formatterOptions={{ currency: currencySymbol }}
        >
          {fiatValue}
        </NumberSizeableTextWrapper>
      ) : null}
    </XStack>
  );
}

function NetworkSearchEmpty({
  title,
  description,
}: {
  title: string;
  description: string;
}) {
  return (
    <YStack
      flex={1}
      alignItems="center"
      justifyContent="center"
      px="$5"
      gap="$2"
    >
      <Icon name="SearchOutline" size="$6" color="$iconSubdued" />
      <SizableText size="$bodyMd" color="$textSubdued">
        {title}
      </SizableText>
      <SizableText size="$bodySm" color="$textDisabled">
        {description}
      </SizableText>
    </YStack>
  );
}

function TokenSearchEmpty({
  title,
  description,
}: {
  title: string;
  description: string;
}) {
  return (
    <YStack
      flex={1}
      alignItems="center"
      justifyContent="center"
      px="$5"
      gap="$2"
    >
      <Icon name="SearchOutline" size="$6" color="$iconSubdued" />
      <SizableText size="$bodyMd" color="$textSubdued">
        {title}
      </SizableText>
      <SizableText size="$bodySm" color="$textDisabled">
        {description}
      </SizableText>
    </YStack>
  );
}

function NetworkSectionLabel({
  children,
  paddingTop,
  paddingBottom,
}: {
  children: string;
  paddingTop: number;
  paddingBottom: number;
}) {
  return (
    <SizableText
      size="$bodySmMedium"
      color="$textSubdued"
      pl={10}
      pt={paddingTop}
      pb={paddingBottom}
    >
      {children}
    </SizableText>
  );
}

export function SwapTokenSelectorDesktop({
  allNetwork,
  networks,
  sameChainNetwork,
  selectedNetwork,
  assetNetworks,
  disableNetworks,
  networkSearchValue,
  tokenSearchValue,
  tokenSearchPlaceholder,
  allNetworksLabel,
  sameChainLabel,
  onNetworkSearchChange,
  onTokenSearchChange,
  onSelectNetwork,
  onDisableNetworksClick,
  onSelectToken,
  listViewRef,
  popularTokens,
  showPopularTokens,
  showLpTokenFilterSwitch,
  showLpTokensOnly,
  onLpTokenFilterChange,
  tokens,
  renderToken,
  currencySymbol,
  tokenListEmptyComponent,
}: ISwapTokenSelectorDesktopProps) {
  const intl = useIntl();
  const networkGroups = useMemo(
    () =>
      buildSwapTokenSelectorNetworkGroups({
        networks: [
          allNetwork,
          ...networks,
          ...(sameChainNetwork ? [sameChainNetwork] : []),
        ],
        searchValue: networkSearchValue,
      }),
    [allNetwork, networkSearchValue, networks, sameChainNetwork],
  );
  const hasNetworkSearch = networkSearchValue.trim().length > 0;
  const normalizedNetworkSearch = networkSearchValue.trim().toLowerCase();
  const allNetworkMatches =
    !hasNetworkSearch ||
    [
      allNetwork.name,
      allNetwork.symbol,
      allNetwork.networkId,
      allNetworksLabel,
    ].some((value) => value.toLowerCase().includes(normalizedNetworkSearch));
  const showNetworkSearchEmpty = hasNetworkSearch && networkGroups.length === 0;
  const selectedNetworkId = selectedNetwork?.networkId;
  const selectedIsAllNetworks = selectedNetwork?.isAllNetworks;
  // One network can be listed in up to three sections (same-chain shortcut,
  // networks with assets, A–Z). Only one row may show the selected state:
  // the row the user pressed, or, before any press, the first visible section
  // in the order above. While searching only the A–Z groups are rendered.
  const [pickedRow, setPickedRow] = useState<{
    section: INetworkSection;
    networkId: string;
  }>();
  const sameChainNetworkId = sameChainNetwork?.networkId;
  const selectedInAssets = assetNetworks.some(
    ({ network }) => network.networkId === selectedNetworkId,
  );
  const resolveSelectedSection = (): INetworkSection => {
    if (hasNetworkSearch) {
      return 'all';
    }
    const picked =
      pickedRow && pickedRow.networkId === selectedNetworkId
        ? pickedRow.section
        : undefined;
    if (
      picked === 'sameChain' &&
      sameChainNetworkId !== undefined &&
      selectedNetworkId === sameChainNetworkId
    ) {
      return 'sameChain';
    }
    if (picked === 'assets' && selectedInAssets) {
      return 'assets';
    }
    if (picked === 'all') {
      return 'all';
    }
    if (
      sameChainNetworkId !== undefined &&
      selectedNetworkId === sameChainNetworkId
    ) {
      return 'sameChain';
    }
    if (selectedInAssets) {
      return 'assets';
    }
    return 'all';
  };
  const selectedSection = resolveSelectedSection();
  const isRowSelected = (section: INetworkSection, networkId: string) =>
    selectedNetworkId === networkId && selectedSection === section;

  return (
    <XStack testID="swap-token-selector-desktop" flex={1} minHeight={0}>
      <YStack
        width={264}
        minHeight={0}
        borderRightWidth={1}
        borderColor="$borderSubdued"
      >
        <YStack p="$3" pb="$2">
          <Input
            testID="swap-token-selector-network-search"
            size="medium"
            height={38}
            pl={34}
            containerProps={{
              height: 38,
              bg: '$bgStrong',
              borderWidth: 0,
              borderRadius: '$3',
            }}
            leftIconName="SearchOutline"
            allowClear
            value={networkSearchValue}
            placeholder={intl.formatMessage({
              id: ETranslations.placeholder_search_networks,
            })}
            onChangeText={onNetworkSearchChange}
          />
        </YStack>
        {showNetworkSearchEmpty && !allNetworkMatches ? (
          <NetworkSearchEmpty
            title={intl.formatMessage({
              id: ETranslations.empty_no_networks_found,
            })}
            description={intl.formatMessage({
              id: ETranslations.description_try_different_name,
            })}
          />
        ) : (
          <ScrollView
            flex={1}
            contentContainerStyle={{ paddingHorizontal: 12, paddingBottom: 4 }}
          >
            {allNetworkMatches ? (
              <NetworkRow
                network={allNetwork}
                selected={selectedIsAllNetworks === true}
                disabled={disableNetworks.includes(allNetwork.networkId)}
                currencySymbol={currencySymbol}
                onPress={() => {
                  if (disableNetworks.includes(allNetwork.networkId)) {
                    onDisableNetworksClick();
                  } else {
                    onSelectNetwork(allNetwork);
                  }
                }}
              />
            ) : null}
            {!hasNetworkSearch && sameChainNetwork ? (
              <>
                <NetworkSectionLabel paddingTop={6} paddingBottom={6}>
                  {intl.formatMessage({ id: ETranslations.label_same_network })}
                </NetworkSectionLabel>
                <NetworkRow
                  network={sameChainNetwork}
                  selected={isRowSelected(
                    'sameChain',
                    sameChainNetwork.networkId,
                  )}
                  disabled={disableNetworks.includes(
                    sameChainNetwork.networkId,
                  )}
                  badgeText={sameChainLabel}
                  currencySymbol={currencySymbol}
                  onPress={() => {
                    if (disableNetworks.includes(sameChainNetwork.networkId)) {
                      onDisableNetworksClick();
                    } else {
                      setPickedRow({
                        section: 'sameChain',
                        networkId: sameChainNetwork.networkId,
                      });
                      onSelectNetwork(sameChainNetwork);
                    }
                  }}
                />
              </>
            ) : null}
            {!hasNetworkSearch && assetNetworks.length > 0 ? (
              <>
                <NetworkSectionLabel paddingTop={22} paddingBottom={6}>
                  {intl.formatMessage({
                    id: ETranslations.network_found_assets_on_networks,
                  })}
                </NetworkSectionLabel>
                {assetNetworks.map(({ network, fiatValue }) => (
                  <NetworkRow
                    key={`asset-${network.networkId}`}
                    network={network}
                    selected={isRowSelected('assets', network.networkId)}
                    disabled={disableNetworks.includes(network.networkId)}
                    fiatValue={fiatValue}
                    currencySymbol={currencySymbol}
                    onPress={() => {
                      if (disableNetworks.includes(network.networkId)) {
                        onDisableNetworksClick();
                      } else {
                        setPickedRow({
                          section: 'assets',
                          networkId: network.networkId,
                        });
                        onSelectNetwork(network);
                      }
                    }}
                  />
                ))}
              </>
            ) : null}
            {!hasNetworkSearch ? (
              <NetworkSectionLabel paddingTop={4} paddingBottom={8}>
                {`${allNetworksLabel} · A–Z`}
              </NetworkSectionLabel>
            ) : null}
            {networkGroups.map(({ network, children }) => (
              <YStack key={network.networkId}>
                <NetworkRow
                  network={network}
                  selected={isRowSelected('all', network.networkId)}
                  disabled={disableNetworks.includes(network.networkId)}
                  currencySymbol={currencySymbol}
                  onPress={() => {
                    if (disableNetworks.includes(network.networkId)) {
                      onDisableNetworksClick();
                    } else {
                      setPickedRow({
                        section: 'all',
                        networkId: network.networkId,
                      });
                      onSelectNetwork(network);
                    }
                  }}
                />
                {children.length > 0 ? (
                  <YStack>
                    {/* One continuous guide line for the whole child group,
                        centered under the parent network logo. */}
                    <Stack
                      position="absolute"
                      left={20}
                      top="$0"
                      bottom="$0"
                      width={1.5}
                      bg="$borderSubdued"
                    />
                    {children.map((child) => (
                      <NetworkRow
                        key={child.networkId}
                        network={child}
                        selected={isRowSelected('all', child.networkId)}
                        disabled={disableNetworks.includes(child.networkId)}
                        indented
                        currencySymbol={currencySymbol}
                        onPress={() => {
                          if (disableNetworks.includes(child.networkId)) {
                            onDisableNetworksClick();
                          } else {
                            setPickedRow({
                              section: 'all',
                              networkId: child.networkId,
                            });
                            onSelectNetwork(child);
                          }
                        }}
                      />
                    ))}
                  </YStack>
                ) : null}
              </YStack>
            ))}
          </ScrollView>
        )}
      </YStack>
      <YStack flex={1} minWidth={0} minHeight={0}>
        <YStack px="$4" pt="$3" pb="$2">
          <Input
            testID="swap-token-selector-token-search"
            size="medium"
            height={38}
            pl={34}
            containerProps={{
              height: 38,
              bg: '$bgStrong',
              borderWidth: 0,
              borderRadius: '$3',
            }}
            leftIconName="SearchOutline"
            allowPaste={tokenSearchValue.length === 0}
            allowClear
            value={tokenSearchValue}
            placeholder={tokenSearchPlaceholder}
            onChangeText={onTokenSearchChange}
          />
        </YStack>
        {showPopularTokens ? (
          <YStack px="$5" pt="$1">
            <SizableText size="$bodyMdMedium" color="$textSubdued">
              {intl.formatMessage({
                id: ETranslations.swap_token_selector_popular_token,
              })}
            </SizableText>
            <SwapPopularTokenGroup
              tokens={popularTokens}
              onSelectToken={onSelectToken}
              variant="desktop"
            />
          </YStack>
        ) : null}
        {!tokenSearchValue.trim() ? (
          <XStack
            height={38}
            alignItems="center"
            justifyContent="space-between"
            pl="$5"
            pr="$4"
          >
            <SizableText size="$bodyMdMedium" color="$textSubdued">
              {selectedNetwork?.isAllNetworks
                ? allNetworksLabel
                : intl.formatMessage(
                    { id: ETranslations.title_tokens_on_network },
                    { network: selectedNetwork?.name ?? '' },
                  )}
            </SizableText>
            {showLpTokenFilterSwitch ? (
              <TokenSelectorLpTokenSwitch
                value={showLpTokensOnly}
                onChange={onLpTokenFilterChange}
                size={ESwitchSize.small}
              />
            ) : null}
          </XStack>
        ) : null}
        <YStack flex={1} minHeight={0}>
          <ListView
            ref={listViewRef}
            data={tokens}
            renderItem={renderToken}
            estimatedItemSize={60}
            ListEmptyComponent={
              tokenListEmptyComponent ?? (
                <TokenSearchEmpty
                  title={intl.formatMessage({
                    id: ETranslations.empty_no_tokens_found,
                  })}
                  description={intl.formatMessage({
                    id: ETranslations.description_check_spelling_or_paste_contract_address,
                  })}
                />
              )
            }
          />
        </YStack>
      </YStack>
    </XStack>
  );
}
